from collections import defaultdict

# Find all sums of two cubes
cube_sums = defaultdict(list)
for a in range(1, 100):
    for b in range(a+1, 100):
        s = a**3 + b**3
        cube_sums[s].append((a, b))

# Find sums that have 2+ representations
multiple_repr = []
for val, pairs in sorted(cube_sums.items()):
    if len(pairs) >= 2:
        multiple_repr.append((val, pairs))

print("Numbers with 2+ cube sum representations:")
for val, pairs in multiple_repr[:10]:
    c = round(val ** (1/3))
    is_cube = c**3 == val
    print(f"{val} (is_cube={is_cube}, cube_root~{c}): {len(pairs)} ways: {pairs}")

print("\n--- Checking cubes only ---")
for val, pairs in multiple_repr[:10]:
    c = round(val ** (1/3))
    if c**3 == val:
        print(f"\n*** {c}³ = {val} has {len(pairs)} representations:")
        for a,b in pairs:
            print(f"  {a}³ + {b}³ = {a**3} + {b**3} = {val}")

from collections import defaultdict

# Find all sums of two cubes up to higher range
cube_sums = defaultdict(list)
for a in range(1, 200):
    for b in range(a+1, 200):
        s = a**3 + b**3
        cube_sums[s].append((a, b))

# Find sums that have 2+ representations
multiple_repr = []
for val, pairs in sorted(cube_sums.items()):
    if len(pairs) >= 2:
        multiple_repr.append((val, pairs))

# Check which are cubes
print("Numbers with 2+ cube sum representations that ARE cubes:")
for val, pairs in multiple_repr:
    c = round(val ** (1/3))
    if c**3 == val:
        print(f"\n*** {c}³ = {val} has {len(pairs)} representations:")
        for a,b in pairs:
            print(f"  {a}³ + {b}³ = {a**3} + {b**3} = {val}")

# Also print first few non-cubes for context
print("\n\nFirst few non-cube results:")
count = 0
for val, pairs in multiple_repr:
    c = round(val ** (1/3))
    if c**3 != val:
        print(f"{val}: {pairs}")
        count += 1
        if count >= 5:
            break

from collections import defaultdict

# Search more efficiently
max_n = 1000
cube_sums = defaultdict(list)
for a in range(1, max_n):
    for b in range(a+1, max_n):
        s = a**3 + b**3
        cube_sums[s].append((a, b))
    if a % 100 == 0:
        print(f"Processing a={a}...")

# Find sums that have 2+ representations
multiple_repr = []
for val, pairs in sorted(cube_sums.items()):
    if len(pairs) >= 2:
        multiple_repr.append((val, pairs))

print(f"\nFound {len(multiple_repr)} numbers with 2+ representations")

# Check which are cubes
print("\nCubes with 2+ cube sum representations:")
found = False
for val, pairs in multiple_repr:
    c = round(val ** (1/3))
    if c**3 == val:
        print(f"\n*** {c}³ = {val} has {len(pairs)} representations:")
        for a,b in pairs:
            print(f"  {a}³ + {b}³ = {a**3} + {b**3} = {val}")
        found = True

if not found:
    print("None found")
    print(f"\nLargest val checked: {max_n-1}³ + {max_n}³ = {(max_n-1)**3 + max_n**3}")

from collections import defaultdict

# Search more efficiently - use smaller range first to verify
max_n = 50
cube_sums = {}
for a in range(1, max_n):
    for b in range(a+1, max_n):
        s = a**3 + b**3
        if s not in cube_sums:
            cube_sums[s] = []
        cube_sums[s].append((a, b))

# Find sums that have 2+ representations
print("Numbers with 2+ cube sum representations:")
for val in sorted(cube_sums.keys()):
    pairs = cube_sums[val]
    if len(pairs) >= 2:
        c = round(val ** (1/3))
        is_cube = c**3 == val
        print(f"{val} (cube={is_cube}, c={c}): {len(pairs)} ways: {pairs}")

